157	    throw new ExecutionError(`${message}\nテーマの色を書き込めなかったので、PowerPoint のファイル ${pptxPath} は消した`);
158	  }
159	  const validate = skillValidate(skill, cache, pptxPath, env);
160	  return { check, pptx: pptxPath, applyThemeOutput, validate };
161	}
