82	  throw new ExecutionError(
83	    `pptx のスキルの ${skill.validate} を、${cache.venvPython} で実行できなかった (終了コード ${String(r.status)}` +
84	      `${r.error === undefined ? "" : `、${r.error.message}`}):\n${output}`,
85	  );
86	}
