88	/** サブコマンド pptx の引数 */
89	export interface PptxOptions extends CheckOptions {
90	  /** pptx のスキルのディレクトリ */
91	  readonly skillDir: string;
92	  /** テーマの色を書き込む処理。省略すると、pptx のスキルの scripts/apply_theme.js を実行する */
93	  readonly applyTheme?: ApplyTheme;
94	}
95	
96	/** サブコマンド pptx の結果 */
97	export interface PptxReport {
98	  readonly check: CheckReport;
99	  /** 書いた PowerPoint のファイル。check に指摘があれば null */
100	  readonly pptx: string | null;
101	  /** テーマの色を書き込む処理の出力 */
102	  readonly applyThemeOutput: string;
103	  /** validate.py の結果。check に指摘があれば null */
104	  readonly validate: ValidateResult | null;
105	}
106	
107	/**
108	 * 前に書いた build/deck.pptx を消す。終了コード 2 で終了しうる確認 (入口の引数・pptx のスキル・ライブラリ・資料のディレクトリ) より前に呼ぶ。
109	 * 入口のサブコマンド pptx は引数の確認より前に、関数 buildPptx は最初に呼ぶ (入口を通らない呼び出しのため)。
110	 * 確認の後に消すと、確認で終了した実行の後に、前の実行のファイルが残る。
111	 * 資料のディレクトリのパスがディレクトリでなければ (無い・通常のファイル)、消すものは無く、後の関数 deckPaths が実行の誤りにする。
112	 * 消せないとき (build/deck.pptx がディレクトリのときなど) は、パスと理由を示す ExecutionError を送出する
113	 */
114	export function removePreviousPptx(deckDir: string): void {
115	  const dir = resolve(deckDir);
116	  if (!existsSync(dir) || !statSync(dir).isDirectory()) return;
117	  const pptxPath = join(dir, "build", "deck.pptx");
118	  try {
119	    rmSync(pptxPath, { force: true });
120	  } catch (e) {
121	    throw new ExecutionError(`前に書いた ${pptxPath} を消せない: ${e instanceof Error ? e.message : String(e)}`);
122	  }
123	}
124	
125	/**
126	 * 資料のディレクトリを検査し、指摘が無ければ build/deck.pptx を書き、テーマの色を書き込み、形式を検査する。
127	 * 前に書いた build/deck.pptx は、最初に消す (ファイルがあることと、最後の実行が書いたことを一致させるため)。
128	 * テーマの色の書き込みが失敗したら、書いたファイルも消す。validate.py が形式の誤りを見つけたときは、調べられるようファイルを残す
129	 */
130	export async function buildPptx(deckDir: string, options: PptxOptions): Promise<PptxReport> {
131	  removePreviousPptx(deckDir);
132	  const env = options.env ?? process.env;
133	  const skill = pptxSkill(options.skillDir);
134	  const cache = installedCache(options);
135	  if (venvState(cache) !== "installed") {
136	    throw new ExecutionError(
137	      `ライブラリ (Python の venv) が、キャッシュのディレクトリ ${cache.venvDir} に入っていない。` +
138	        "サブコマンド setup status で状態を確認し、setup install で入れる",
139	    );
140	  }
141	  const paths = deckPaths(deckDir);
142	  const pptxPath = join(paths.buildDir, "deck.pptx");
143	  const themePath = join(paths.buildDir, "theme.json");
144	
145	  const check = await checkDeck(deckDir, options);
146	  if (check.deck === null) return { check, pptx: null, applyThemeOutput: "", validate: null };
147	
148	  writeFileSync(pptxPath, await renderPptx(check.deck, loadPptxGen(cache.nodeModulesDir)));
149	  writeFileSync(themePath, `${JSON.stringify(applyThemeInput(check.deck.theme), null, 2)}\n`);
150	  const applyTheme = options.applyTheme ?? skillApplyTheme(skill, cache, env);
151	  let applyThemeOutput: string;
152	  try {
153	    applyThemeOutput = applyTheme(pptxPath, themePath);
154	  } catch (e) {
155	    rmSync(pptxPath, { force: true });
156	    const message = e instanceof Error ? e.message : String(e);
157	    throw new ExecutionError(`${message}\nテーマの色を書き込めなかったので、PowerPoint のファイル ${pptxPath} は消した`);
158	  }
159	  const validate = skillValidate(skill, cache, pptxPath, env);
160	  return { check, pptx: pptxPath, applyThemeOutput, validate };
161	}
